steps.script:
function transform(ctx) {
  var MAP = { "移动": "cmcc", "电信": "telecom", "联通": "unicom", "教师": "xyw" };
  var isp = (ctx.isp || "").trim();
  var s = "";
  if (isp) { s = MAP[isp] !== undefined ? MAP[isp] : (isp.charAt(0) === "@" ? isp.substring(1) : ""); }
  var full = (ctx.username || "") + (s ? "@" + s : "");
  var mac = (ctx.local_mac || "").replace(/:/g, "").toLowerCase() || "000000000000";
  return { ua: url_encode(",0," + full), ep: url_encode(ctx.password || ""), mac: mac };
}
